#include <iostream>
#include <string>
#include <vector>

int main() {
    std::string s;
    std::getline(std::cin, s);
    int cnt = 0;
    std::string gk = s;
    // Replace "at" with "@"
    size_t pos = 0;
    while ((pos = gk.find("at", pos)) != std::string::npos) {
        gk.replace(pos, 2, "@");
        pos += 1;
    }
    // Replace "dot" with "."
    pos = 0;
    while ((pos = gk.find("dot", pos)) != std::string::npos) {
        gk.replace(pos, 3, ".");
        pos += 1;
    }
    std::vector<char> k(gk.begin(), gk.end());
    int n = k.size();

    if (n > 0 && k[0] == '.') {
        k[0] = 'd'; // "dot" will be reconstructed later if needed
    }
    if (n > 0 && k[n - 1] == '.') {
        k[n - 1] = 'd';
    }
    if (n > 0 && k[0] == '@') {
        k[0] = 'a'; // "at" will be reconstructed later if needed
    }
    if (n > 0 && k[n - 1] == '@') {
        k[n - 1] = 'a';
    }

    for (int x = 0; x < n; x++) {
        if (k[x] == '@' && cnt == 0) {
            cnt = 1;
        } else if (k[x] == '@') {
            k[x] = 'a'; // "at"
        }
        std::cout << k[x];
    }
    return 0;
}
